/* APLUS AI Tutor Database V1 — P6 Cloze / Editing Expansion Batch 04 */
window.APLUS_AI_DB_V1_P6_CLOZE_EDITING_EXPANSION_BATCH04 = [
{id:"P6-CE-B04-001",type:"cloze",skill:"past perfect",text:"When we reached the cinema, the film ___ already started.",options:["had","has","is","will"],answer:"had",explanation:"The past perfect marks the action that happened before another past event.",difficulty:3},
{id:"P6-CE-B04-002",type:"cloze",skill:"present perfect",text:"I ___ never seen such a large butterfly before.",options:["have","has","had","am"],answer:"have",explanation:"Use present perfect with the subject 'I' for an experience up to the present.",difficulty:2},
{id:"P6-CE-B04-003",type:"cloze",skill:"connector",text:"The path was muddy, ___ we walked carefully.",options:["so","although","unless","before"],answer:"so",explanation:"So introduces the result of the muddy path.",difficulty:2},
{id:"P6-CE-B04-004",type:"cloze",skill:"preposition",text:"The pupils waited ___ the bus stop.",options:["at","in","on","to"],answer:"at",explanation:"The standard expression is 'wait at the bus stop'.",difficulty:2},
{id:"P6-CE-B04-005",type:"cloze",skill:"word form",text:"The scientist made an important ___.",options:["discovery","discover","discovering","discovered"],answer:"discovery",explanation:"A noun is needed after 'made an important'.",difficulty:3},
{id:"P6-CE-B04-006",type:"cloze",skill:"quantifier",text:"There are only ___ chairs left, so some pupils must stand.",options:["a few","a little","much","any"],answer:"a few",explanation:"Chairs are countable plural nouns, so 'a few' is appropriate.",difficulty:2},
{id:"P6-CE-B04-007",type:"cloze",skill:"relative pronoun",text:"The woman ___ won the award thanked her team.",options:["who","which","where","when"],answer:"who",explanation:"Who refers to a person.",difficulty:2},
{id:"P6-CE-B04-008",type:"cloze",skill:"modal",text:"You ___ wear a helmet when cycling on this track.",options:["must","might","would","could have"],answer:"must",explanation:"Must expresses a strong requirement.",difficulty:2},
{id:"P6-CE-B04-009",type:"cloze",skill:"article",text:"We visited ___ museum near the river that our teacher recommended.",options:["the","a","an","no article"],answer:"the",explanation:"The relative clause identifies a specific museum.",difficulty:3},
{id:"P6-CE-B04-010",type:"cloze",skill:"phrasal verb",text:"Please ___ your shoes before entering the laboratory.",options:["take off","take after","look into","bring up"],answer:"take off",explanation:"Take off means remove clothing or footwear.",difficulty:2},
{id:"P6-CE-B04-011",type:"editing",skill:"subject-verb agreement",text:"Each of the pupils have submitted the form.",answer:"Each of the pupils has submitted the form.",explanation:"Each is singular and takes 'has'.",difficulty:3},
{id:"P6-CE-B04-012",type:"editing",skill:"past tense",text:"Yesterday, Daniel go to the library after school.",answer:"Yesterday, Daniel went to the library after school.",explanation:"Yesterday signals a completed past action, so 'went' is required.",difficulty:2},
{id:"P6-CE-B04-013",type:"editing",skill:"preposition",text:"She is good in solving difficult puzzles.",answer:"She is good at solving difficult puzzles.",explanation:"The standard collocation is 'good at'.",difficulty:3},
{id:"P6-CE-B04-014",type:"editing",skill:"uncountable noun",text:"The teacher gave us several useful advices.",answer:"The teacher gave us several useful pieces of advice.",explanation:"Advice is uncountable; use 'pieces of advice' when counting.",difficulty:4},
{id:"P6-CE-B04-015",type:"editing",skill:"reported question",text:"Ben asked me where was the station.",answer:"Ben asked me where the station was.",explanation:"In an embedded reported question, use statement word order.",difficulty:4},
{id:"P6-CE-B04-016",type:"editing",skill:"comparative",text:"This puzzle is more easier than the previous one.",answer:"This puzzle is easier than the previous one.",explanation:"Easier already contains the comparative form, so 'more' is unnecessary.",difficulty:3},
{id:"P6-CE-B04-017",type:"editing",skill:"infinitive",text:"Mum reminded me bring my jacket.",answer:"Mum reminded me to bring my jacket.",explanation:"Remind someone is followed by the infinitive 'to bring'.",difficulty:3},
{id:"P6-CE-B04-018",type:"editing",skill:"passive voice",text:"The winning design was choose by the judges.",answer:"The winning design was chosen by the judges.",explanation:"Passive voice requires the past participle 'chosen'.",difficulty:3},
{id:"P6-CE-B04-019",type:"editing",skill:"first conditional",text:"If it rains tomorrow, we will stayed indoors.",answer:"If it rains tomorrow, we will stay indoors.",explanation:"After will, use the base form 'stay'.",difficulty:3},
{id:"P6-CE-B04-020",type:"cloze",skill:"cohesive device",text:"First, read the instructions carefully. ___, check that you have all the materials.",options:["Next","Although","Unless","Because"],answer:"Next",explanation:"Next signals the following step in a sequence.",difficulty:2}
];